        v.setGovernanceOwnerDepartmentId(p.getGovernanceOwnerDepartmentId()); v.setGovernanceOwnerGroupId(p.getGovernanceOwnerGroupId()); v.setGovernanceScopeClass(enumValue(A2AGovernanceScopeClass.class,p.getGovernanceScopeClass(),A2AGovernanceScopeClass.TENANT)); v.setGovernanceScopeStatus(p.getGovernanceScopeStatus()==null?"RESOLVED":p.getGovernanceScopeStatus());
        v.setAllowedTaskTypes(list(p.getAllowedTaskTypesJson())); v.setAllowedServiceCodes(list(p.getAllowedServiceCodesJson())); v.setAllowedCapabilityCodes(list(p.getAllowedCapabilityCodesJson()));
