    private String objectJson(Object v) { try { return v == null ? null : mapper.writeValueAsString(v); } catch (Exception e) { throw new IllegalStateException("A2A JSON serialization failed", e); } }
    private <T> T object(String v, Class<T> type) { try { return v == null || v.isBlank() ? null : mapper.readValue(v, type); } catch (Exception e) { throw new IllegalStateException("A2A JSON deserialization failed", e); } }
    private List<String> list(String v) { try { return v == null || v.isBlank() ? List.of() : mapper.readValue(v, new TypeReference<List<String>>(){}); } catch (Exception e) { return List.of(); } }
    private <E extends Enum<E>> E enumValue(Class<E> c, String v, E d) { try { return v == null ? d : Enum.valueOf(c, v); } catch (Exception e) { return d; } }
